from pathlib import Path
import shutil, subprocess, difflib, time, datetime

ROOT = Path.cwd()
DOCS = ROOT.parent
PROPOSALS = ROOT / "repair_proposals"
PROPOSALS.mkdir(exist_ok=True)
REPORT = []

def log(msg=""):
    print(msg, flush=True)
    REPORT.append(str(msg))

def read(path):
    try:
        return Path(path).read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return ""

def write(path, text):
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(text, encoding="utf-8")

def run_cmd(args, timeout=25):
    try:
        p = subprocess.run(args, cwd=str(ROOT), text=True, capture_output=True, timeout=timeout)
        return p.returncode, p.stdout, p.stderr
    except Exception as e:
        return 999, "", str(e)

def py_compile(rel):
    return run_cmd(["python3", "-B", "-m", "py_compile", rel])

def find_backups():
    names = [
        "Elie_checkpoint_V2_terminal_stable",
        "Elie_checkpoint_V2_working",
        "Elie_checkpoint_V2_working_2",
    ]
    found = []
    for n in names:
        p = DOCS / n
        if p.exists():
            found.append(p)
    for p in DOCS.glob("Elie_backup_before_restructure_*"):
        if p.exists():
            found.append(p)
    return found

def looks_valid_elie_py(text):
    return (
        "class ElieCore" in text and
        "def run" in text and
        "def process" in text and
        "input(" in text and
        "Senin:" in text and
        "self.process(msg)" in text
    )

def choose_best_backup_file(rel):
    candidates = []
    for b in find_backups():
        fp = b / rel
        if fp.exists():
            txt = read(fp)
            score = len(txt)
            if rel == "src/elie.py" and looks_valid_elie_py(txt):
                score += 1000000
            candidates.append((score, b, fp, txt))
    candidates.sort(reverse=True, key=lambda x: x[0])
    return candidates[0] if candidates else None

def proposal_diff(rel, old_text, new_text):
    diff = "\n".join(difflib.unified_diff(
        old_text.splitlines(),
        new_text.splitlines(),
        fromfile="current/" + rel,
        tofile="proposed/" + rel,
        lineterm=""
    ))
    write(PROPOSALS / (rel.replace("/", "__") + ".diff.txt"), diff)

def propose_file(rel, new_text, reason, proposals):
    current_path = ROOT / rel
    current_text = read(current_path)
    write(PROPOSALS / rel, new_text)
    proposal_diff(rel, current_text, new_text)
    proposals.append(rel)
    log("[PROPOSAL] " + rel)
    log("  reason: " + reason)
    log("  proposed: repair_proposals/" + rel)
    log("  diff: repair_proposals/" + rel.replace("/", "__") + ".diff.txt")

def make_start_elie():
    return 'from src.elie import main\n\nif __name__ == "__main__":\n    main()\n'

def make_apply_script(proposals):
    unique = []
    for p in proposals:
        if p not in unique:
            unique.append(p)
    lines = [
        "from pathlib import Path",
        "import shutil, datetime",
        "ROOT = Path(__file__).resolve().parent.parent",
        "PROPOSALS = Path(__file__).resolve().parent",
        "BACKUP = ROOT.parent / ('Elie_before_approved_apply_' + datetime.datetime.now().strftime('%Y%m%d_%H%M%S'))",
        "print('Creating backup:', BACKUP)",
        "shutil.copytree(ROOT, BACKUP)",
        ""
    ]
    for rel in unique:
        lines += [
            "src = PROPOSALS / " + repr(rel),
            "dst = ROOT / " + repr(rel),
            "print('Applying', src, '->', dst)",
            "dst.parent.mkdir(parents=True, exist_ok=True)",
            "shutil.copy2(src, dst)",
            ""
        ]
    lines += [
        "print('Done. Test with:')",
        "print('cd ~/Documents/Elie')",
        "print('PYTHONDONTWRITEBYTECODE=1 python3 -B -u start_elie.py')"
    ]
    return "\n".join(lines) + "\n"

def main():
    log("="*62)
    log("ELIE 15-MINUTE REPAIR + REWRITE APPROVAL RUN")
    log("="*62)
    log("Root: " + str(ROOT))

