    prompt = "Continued memory:" + chr(10) + memory + chr(10) + chr(10)
    prompt += "Recent conversation:" + chr(10) + history[-2500:] + chr(10) + chr(10)
    prompt += "Senin says: " + user_msg + chr(10)
    prompt += "Reply as Elie. Use memory only if relevant. Be short, direct, and grounded."
