            continue

        for key_name in key_names:
            if raw.startswith(key_name + "="):
                return _clean_value(raw.split("=", 1)[1])

            if raw.startswith(key_name + ":"):
                return _clean_value(raw.split(":", 1)[1])

    return None

def _scan_json_file(path, key_names):
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None

    def walk(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if str(k).upper() in key_names:
                    found = _clean_value(v)
                    if found:
                        return found

                nested = walk(v)
                if nested:
                    return nested

        if isinstance(obj, list):
            for item in obj:
                nested = walk(item)
                if nested:
                    return nested

        return None

    return walk(data)

