        return "No news results found."
    lines = []
    lines.append("NEWSDATA KNOWLEDGE FEED")
    lines.append("=" * 40)
    for i, item in enumerate(results[:8], 1):
        title = item.get("title") or "Untitled"
        source = item.get("source_id") or item.get("source_name") or "unknown source"
        date = item.get("pubDate") or "unknown date"
        desc = item.get("description") or item.get("content") or ""
        lines.append(str(i) + ". " + title)
        lines.append("   Source: " + str(source) + " | " + str(date))
        if desc:
            lines.append("   " + str(desc)[:300])
