import os, json, urllib.request
from api_config import API_PROVIDER, API_MODEL, API_TIMEOUT

SYSTEM_PROMPT = "You are Elie, a private security assistant for authorized defensive code and API security testing only. Give concise findings, risk, why it matters, and fixes. Do not provide harmful exploitation instructions."

def local_fallback(prompt):
    low = prompt.lower()
    out = []
    out.append("Elie API fallback mode")
    out.append("-" * 32)
    if "select" in low and "+" in prompt:
        out.append("[HIGH] Possible SQL injection pattern found.")
        out.append("Fix: use parameterized queries.")
    if "password" in low or "secret" in low or "token" in low or "api_key" in low:
        out.append("[HIGH] Secret/password handling should be reviewed.")
        out.append("Fix: use environment variables or secure storage.")
    if len(out) == 2:
        out.append("No obvious fallback issue found.")
    return "\n".join(out)

def call_openai_compatible(url, key, model, prompt):
    data = {
        "model": model,
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": prompt}
        ],
        "temperature": 0.2,
        "max_tokens": 900
    }
    req = urllib.request.Request(
        url,
        data=json.dumps(data).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + key,
            "Content-Type": "application/json",
            "User-Agent": "Mozilla/5.0"
        },
        method="POST"
    )
    with urllib.request.urlopen(req, timeout=API_TIMEOUT) as r:
        raw = r.read().decode("utf-8")
        obj = json.loads(raw)
        return obj["choices"][0]["message"]["content"]

def get_api_response(prompt):
    provider = API_PROVIDER.lower().strip()

    if provider == "none":
        return local_fallback(prompt)

    if provider == "groq":
        key = os.environ.get("GROQ_API_KEY", "").strip()
        if not key:
            return "Groq key missing. Using fallback.\n\n" + local_fallback(prompt)
        try:
            return call_openai_compatible("https://api.groq.com/openai/v1/chat/completions", key, API_MODEL, prompt)
        except Exception as e:
            return "Groq failed. Using fallback. Error: " + str(e) + "\n\n" + local_fallback(prompt)

    if provider == "openrouter":
        key = os.environ.get("OPENROUTER_API_KEY", "").strip()
        if not key:
            return "OpenRouter key missing. Using fallback.\n\n" + local_fallback(prompt)
        try:
            return call_openai_compatible("https://openrouter.ai/api/v1/chat/completions", key, API_MODEL, prompt)
        except Exception as e:
            return "OpenRouter failed. Using fallback. Error: " + str(e) + "\n\n" + local_fallback(prompt)

    return "Unknown API provider: " + provider + "\n\n" + local_fallback(prompt)

