from api_cooldown import set_cooldown, is_cooling, looks_rate_limited

API_CIRCLE = ["groq", "gemini", "openrouter"]
API_INDEX = {"value": 0}
DEFAULT_COOLDOWN_SECONDS = 300

def local_fallback(system, prompt, reason=""):
    text = "LOCAL FALLBACK ACTIVE" + chr(10)
    text += "Reason: " + str(reason) + chr(10)
    text += "No external API available. Report-only mode." + chr(10)
    text += chr(10) + "Prompt summary:" + chr(10) + str(prompt)[:2200]
    return True, text

def call_provider(name, system, prompt):
    if name == "groq":
        return call_groq(system, prompt)
    if name == "gemini":
        return call_gemini(system, prompt)
    if name == "openrouter":
        return call_openrouter(system, prompt)
    if name == "local":
        return local_fallback(system, prompt, "local selected")
    return False, "Unknown provider: " + str(name)

def next_available_provider():
    total = len(API_CIRCLE)
    if total == 0:
        return None
    for _ in range(total):
        idx = API_INDEX["value"] % total
        name = API_CIRCLE[idx]
        API_INDEX["value"] = (idx + 1) % total
        cooling, left, reason = is_cooling(name)
        if not cooling:
            return name
        pass  # quieted Elie log
    return None

def circle_call(system, prompt, purpose="general"):
    tried = []
    total = len(API_CIRCLE)
    for _ in range(total):
        name = next_available_provider()
        if not name:
            break
        tried.append(name)
        pass  # quieted Elie log
        ok, res = call_provider(name, system, prompt)
        if looks_rate_limited(res):
            set_cooldown(name, DEFAULT_COOLDOWN_SECONDS, "rate limit detected")
            continue
        if ok:
            return True, res, name, tried
        pass  # quieted Elie log
    ok, res = local_fallback(system, prompt, "all APIs unavailable or cooling")
    return ok, res, "local", tried

def api_circle_status():
    rows = []
    for name in API_CIRCLE:
        cooling, left, reason = is_cooling(name)
        state = "cooling " + str(left) + "s" if cooling else "ready"
        rows.append(name + ": " + state + (" - " + reason if reason else ""))
    return chr(10).join(rows)

