def collect_recent_text(limit=12000):
    chunks = []
    for folder in [LOG_DIR, REPORT_DIR]:
        if not os.path.exists(folder):
            continue
        files = []
        for name in os.listdir(folder):
            path = os.path.join(folder, name)
            if os.path.isfile(path):
                files.append(path)
        files.sort(key=lambda p: os.path.getmtime(p), reverse=True)
        for path in files[:8]:
            text = read_file(path)
            if text:
                chunks.append("FILE: " + path + chr(10) + text[-2500:])
    joined = chr(10).join(chunks)
    return joined[-limit:]

