    low = text.lower()
    lessons = []
    if "command not found" in low:
        lessons.append("Senin often hits shell command issues. Future instructions must be smaller, one chunk at a time, with clear prompt-state checks.")
    if ">>>" in text or "python mode" in low:
        lessons.append("Senin often gets stuck inside Python REPL. Elie should always detect prompt state before giving commands.")
    if "telegram" in low and ("401" in low or "unauthorized" in low):
        lessons.append("Telegram bridge code can work while token fails. Elie should explain 401 as invalid token, not broken code.")
    if "syntaxerror" in low or "indentationerror" in low:
        lessons.append("Large patch commands break easily on iPhone. Prefer new files and echo chunks over inline Python patching.")
