import os

CODE_FOLDER = "code"

def read_code(name):
    path = os.path.join(CODE_FOLDER, name)
    if not os.path.exists(path):
        return None, "File not found: " + name
    try:
        return open(path, "r", encoding="utf-8", errors="ignore").read(), None
    except Exception as e:
        return None, "Could not read file: " + str(e)

def find_lines(text, keys):
    hits = []
    for i, line in enumerate(text.splitlines(), 1):
        low = line.lower()
        for key in keys:
            if key in low:
                hits.append((i, line.strip()[:120]))
                break
    return hits

def section(title, hits):
    out = []
    out.append(title)
    out.append("-" * len(title))
    if not hits:
        out.append("None found.")
    else:
        for line_no, code in hits:
            out.append("Line " + str(line_no) + ": " + code)
    out.append("")
    return out

def build_map(name):
    text, err = read_code(name)
    if err:
        return err

    inputs = find_lines(text, ["input(", "request.", "request[", "params", "query", "body", "form", "argv"])
    database = find_lines(text, ["sqlite3", "connect(", "cursor", "execute(", "select ", "insert ", "update ", "delete "])
    auth = find_lines(text, ["password", "login", "auth", "token", "session", "cookie", "jwt"])
    routes = find_lines(text, ["@app.route", "router.", "route(", "get(", "post(", "put(", "delete("])
    risky = find_lines(text, ["select", "+", "eval(", "exec(", "os.system", "subprocess", "innerhtml", "document.write"])

    out = []
    out.append("Elie Shannon Map")
    out.append("File: " + name)
    out.append("=" * 32)
    out.append("")
    out += section("Inputs", inputs)
    out += section("Routes / Endpoints", routes)
    out += section("Database / Queries", database)
    out += section("Auth / Session / Password", auth)
    out += section("Risky Path Clues", risky)
    out.append("Shannon-style summary")
    out.append("---------------------")
    if inputs and database:
        out.append("- Possible path: user input -> database query.")
    if auth and database:
        out.append("- Possible path: auth/password logic -> database.")
    if risky:
        out.append("- Risk clues found. Run quick/deep for defensive review.")
    if not inputs and not database and not auth and not routes and not risky:
        out.append("- No obvious Shannon-style paths found in this file.")
    out.append("")
    out.append("Next safe actions:")
    out.append("- quick " + name)
    out.append("- deep " + name)
    out.append("- report " + name)
    return "\n".join(out)

