        findings.append(("HIGH", "Possible hardcoded secret", "Move secrets to environment variables."))
    if "innerhtml" in low or "document.write" in low:
        findings.append(("HIGH", "Possible XSS", "Use textContent/safe DOM APIs and sanitize input."))
    if "eval(" in low:
        findings.append(("HIGH", "Dangerous eval usage", "Avoid eval and dynamic code execution."))
    if "os.system" in low or "subprocess" in low or "exec(" in low:
        findings.append(("HIGH", "Possible unsafe command execution", "Avoid shell execution with user input."))
    if "debug=true" in low or "debug = true" in low:
        findings.append(("MEDIUM", "Debug mode enabled", "Disable debug mode in production."))
    if "access-control-allow-origin" in low and "*" in text:
        findings.append(("MEDIUM", "Weak CORS pattern", "Restrict CORS to trusted origins."))
    if "cookie" in low:
        findings.append(("MEDIUM", "Cookie/security review needed", "Use HttpOnly, Secure, and SameSite for sensitive cookies."))

