        lines.append("No obvious issue found by quick scan.")
        lines.append("Note: quick scan cannot detect every logic bug.")
    else:
        for i, item in enumerate(findings, 1):
            risk, title, fix = item
            lines.append(str(i) + ". [" + risk + "] " + title)
