import os, base64, hashlib
SECURE_DIR = "api/secure"
CACHE = {}
MAGIC = "RayKEY:"

def vault_path(name):
    os.makedirs(SECURE_DIR, exist_ok=True)
    return os.path.join(SECURE_DIR, name + ".key.enc")

def stream(password, n):
    out = b""
    i = 0
    while len(out) < n:
        out += hashlib.sha256((password + ":" + str(i)).encode()).digest()
        i += 1
    return out[:n]

def xor_bytes(raw, password):
    pad = stream(password, len(raw))
    return bytes([raw[i] ^ pad[i] for i in range(len(raw))])

def save_key(name):
    key = input("Paste [redacted]
    password = [redacted]
    raw = (MAGIC + key).encode("utf-8")
    enc = base64.b64encode(xor_bytes(raw, password)).decode("ascii")
    open(vault_path(name), "w", encoding="utf-8").write(enc)
    os.chmod(vault_path(name), 0o600)
    print("Saved encrypted key:", vault_path(name))

def load_key(name):
    if name in CACHE:
        return CACHE[name]
    path = vault_path(name)
    if not os.path.exists(path):
        return ""
    password = [redacted]
    if not password= [redacted]
        return ""
    try:
        enc = open(path, "r", encoding="utf-8").read().strip()
        raw = base64.b64decode(enc.encode("ascii"))
        dec = xor_bytes(raw, password).decode("utf-8", errors="ignore")
        if not dec.startswith(MAGIC):
            print("Wrong admin password or damaged vault.")
            return ""
        key = dec[len(MAGIC):].strip()
        CACHE[name] = key
        return key
    except Exception as e:
        print("Vault unlock failed:", str(e))
        return ""

if __name__ == "__main__":
    import sys
    if len(sys.argv) < 3:
        print("Use:")
        print("python api/key_vault.py save groq")
        print("python api/key_vault.py test groq")
        raise SystemExit
    cmd = sys.argv[1].strip().lower()
    name = sys.argv[2].strip().lower()
    if cmd == "save":
        save_key(name)
    elif cmd == "test":
        key = load_key(name)
        print("Unlocked:", bool(key))
        if key:
            print("Key prefix:", key[:4] + "...")

