import os, json, urllib.request
from api.api_settings import API_TIMEOUT, MAX_OUTPUT_TOKENS
from api.key_vault import load_key
from api.api_keys import ask_key

PROVIDER_NAME = "gemini"
DEFAULT_MODEL = "gemini-2.5-flash"
API_BASE = "https://generativelanguage.googleapis.com/v1beta/models/"

def has_key():
    return os.path.exists("api/secure/gemini.key.enc") or bool(os.environ.get("GEMINI_API_KEY", "").strip())

def call_gemini(system_prompt, user_prompt, model=None):
    key = os.environ.get("GEMINI_API_KEY", "").strip()
    if not key:
        key = load_key("gemini")
    if not key:
        key = ask_key("gemini")
    if not key:
        return False, "Gemini API key missing."
    if model is None:
        model = DEFAULT_MODEL
    url = API_BASE + model + ":generateContent"
    full_prompt = system_prompt + chr(10) + chr(10) + user_prompt
    data = {
        "contents": [
            {"parts": [{"text": full_prompt}]}
        ],
        "generationConfig": {
            "temperature": 0.2,
            "maxOutputTokens": MAX_OUTPUT_TOKENS
        }
    }
    try:
        req = urllib.request.Request(
            url,
            data=json.dumps(data).encode("utf-8"),
            headers={"x-goog-api-key": key, "Content-Type": "application/json", "User-Agent": "Mozilla/5.0"},
            method="POST"
        )
        with urllib.request.urlopen(req, timeout=API_TIMEOUT) as r:
            obj = json.loads(r.read().decode("utf-8"))
            parts = obj["candidates"][0]["content"]["parts"]
            text = ""
            for part in parts:
                text += part.get("text", "")
            return True, text
    except Exception as e:
        return False, "Gemini failed: " + str(e)

