class GroqClient:
    def __init__(self):
        self.api_url = "https://api.groq.com/openai/v1/chat/completions"
        self.model = os.environ.get("RAY_GROQ_MODEL", "llama-3.1-8b-instant")

    def load_key(self):
        key = os.environ.get("GROQ_API_KEY", "").strip()
        if key:
            return key
        key_file = ROOT / "ray" / "vault" / "groq_key.txt"
        if key_file.exists():
            return key_file.read_text(encoding="utf-8").strip()
        return ""

    def has_key(self):
        return bool(self.load_key())

    def chat(self, prompt):
        key = self.load_key()
        if not key:
            return "Groq API key missing. Add GROQ_API_KEY or ray/vault/groq_key.txt. Local /map and /report still work."

        payload = {
            "model": self.model,
            "messages": [
                {"role": "system", "content": "You are Ray, a safe Shannon-style authorized code/app/API analysis assistant."},
                {"role": "user", "content": prompt}
            ],
            "temperature": 0.35,
            "max_tokens": 900
        }

        req = request.Request(
            self.api_url,
            data=json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json", "Authorization": f"Bearer {key}"},
            method="POST"
        )

        try:
            with request.urlopen(req, timeout=60) as resp:
                body = json.loads(resp.read().decode("utf-8"))
                return body["choices"][0]["message"]["content"]
        except error.HTTPError as e:
            detail = e.read().decode("utf-8", errors="ignore")
            return f"Groq API error {e.code}: {detail[:500]}"
        except Exception as e:
            return f"Groq request failed: {e}"

