class SafetyGate:
    def __init__(self):
        self.blocked_phrases = [
            "steal password", "steal token", "phishing", "malware", "ransomware",
            "keylogger", "persistence", "bypass detection", "evade antivirus",
            "hack this site", "ddos", "credential stuffing"
        ]

    def check(self, text):
        low = text.lower()
        for phrase in self.blocked_phrases:
            if phrase in low:
                return {
                    "allowed": False,
                    "message": "Ray safety block: I can help with authorized defensive analysis and safe fixes, not abuse."
                }
        return {"allowed": True, "message": "allowed"}

