import os, datetime
from api.key_vault import unlock_many
from api_circle import circle_call, api_circle_status
from elise_core import elise_system_prompt

MEMORY_FILE = "memory/elie_chat_memory.txt"
os.makedirs("memory", exist_ok=True)
os.makedirs("logs", exist_ok=True)

def looks_secret(text):
    low = str(text).lower()
    danger = ["token", "api key", "apikey", "password", "secret", "bearer ", "telegram bot token"]
    return any(x in low for x in danger)

def load_memory():
    mem = read_file(MEMORY_FILE).strip()
    if not mem:
        return "No continued memory saved yet."
    return mem[-3500:]

def remember_line(text):
    if looks_secret(text):
        return "Blocked memory save because it may contain a secret."
    append_file(MEMORY_FILE, "[" + now() + "] " + str(text))
    return "Saved to continued memory."

def auto_memory_from_message(msg):
    low = msg.lower()
    if looks_secret(msg):
        return None
    if "remember" in low or "from now on" in low or "going forward" in low:
        return "Senin said: " + msg
    if "lucy" in low and "elise" in low:
        return "Lucy and Elise/Elie must stay separate. Lucy is companion presence; Elise/Elie is operational/control side."
    if "too generic" in low or "generic" in low:
        return "Senin dislikes generic assistant replies. Elie should be direct, practical, and less corporate."
    if "iphone" in low or "a-shell" in low or "shell" in low:
        return "Senin is building from iPhone/a-Shell, so instructions must be small, clear, and prompt-state aware."
    return None

def build_prompt(user_msg, history):
    memory = load_memory()
    prompt = "Continued memory:" + chr(10) + memory + chr(10) + chr(10)
    prompt += "Recent conversation:" + chr(10) + history[-2500:] + chr(10) + chr(10)
    prompt += "Senin says: " + user_msg + chr(10)
    prompt += "Reply as Elie. Use memory only if relevant. Be short, direct, and grounded."
