import json, urllib.parse, urllib.request
from api.api_settings import API_TIMEOUT
from api.key_vault import load_key

TOOL_NAME = "newsdata"
API_URL = "https://newsdata.io/api/1/latest"

def get_key():
    key = load_key("newsdata")
    if key:
        return key
    return None

def build_url(query="", country="", category="", language="en", size=5):
    key = get_key()
    if not key:
        return None
    params = {"apikey": key, "language": language}
    if query:
        params["q"] = query
    if country:
        params["country"] = country
    if category:
        params["category"] = category
    if size:
        params["size"] = str(size)
    return API_URL + "?" + urllib.parse.urlencode(params)

def fetch_news(query="", country="", category="", language="en", size=5):
    url = build_url(query, country, category, language, size)
    if not url:
        return False, "Newsdata key missing or vault locked."
    try:
        req = urllib.request.Request(url, method="GET")
        req.add_header("User-Agent", "Elise Private Assistant")
        with urllib.request.urlopen(req, timeout=API_TIMEOUT) as r:
            raw = r.read().decode("utf-8", errors="ignore")
        return True, json.loads(raw)
    except Exception as e:
        return False, "Newsdata failed: " + str(e)

def format_news(data):
    if not isinstance(data, dict):
        return str(data)
    results = data.get("results", [])
    if not results:
        return "No news results found."
    lines = []
    lines.append("NEWSDATA KNOWLEDGE FEED")
    lines.append("=" * 40)
    for i, item in enumerate(results[:8], 1):
        title = item.get("title") or "Untitled"
        source = item.get("source_id") or item.get("source_name") or "unknown source"
        date = item.get("pubDate") or "unknown date"
        desc = item.get("description") or item.get("content") or ""
        lines.append(str(i) + ". " + title)
        lines.append("   Source: " + str(source) + " | " + str(date))
        if desc:
            lines.append("   " + str(desc)[:300])
        lines.append("")
    return chr(10).join(lines)

def knowledge_feed(query="", country="", category="", language="en", size=5):
    ok, data = fetch_news(query, country, category, language, size)
    if not ok:
        return False, str(data)
    return True, format_news(data)

import json, urllib.request
from api.api_settings import API_TIMEOUT, MAX_OUTPUT_TOKENS
from api.key_vault import load_key, ask_key

PROVIDER_NAME = "openrouter"
DEFAULT_MODEL = "openrouter/auto"
API_URL = "https://openrouter.ai/api/v1/chat/completions"

def get_key():
    key = load_key("openrouter")
    if key:
        return key
    return ask_key("openrouter")

def call_openrouter(system_prompt, user_prompt, model=DEFAULT_MODEL):
    key = get_key()
    if not key:
        return False, "OpenRouter key missing."
    data = {
        "model": model,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt}
        ],
        "temperature": 0.2,
        "max_tokens": MAX_OUTPUT_TOKENS
    }
    body = json.dumps(data).encode("utf-8")
    req = urllib.request.Request(API_URL, data=body, method="POST")
    req.add_header("Authorization", "Bearer " + key)
    req.add_header("Content-Type", "application/json")
    req.add_header("HTTP-Referer", "http://localhost")
    req.add_header("X-Title", "Elise Private Assistant")
    try:
        with urllib.request.urlopen(req, timeout=API_TIMEOUT) as r:
            raw = r.read().decode("utf-8", errors="ignore")
        obj = json.loads(raw)
        text = obj["choices"][0]["message"]["content"]
        return True, text
    except Exception as e:
        return False, "OpenRouter failed: " + str(e)

