import os, datetime

WATCH_FILES = [
    "main.py",
    "elie.py",
    "elie_shannon.py",
    "shannon_core.py",
    "shannon_ai.py",
    "approval_gate.py",
    "scope_config.py",
    "api_lock.py",
    "elie_identity.py"
]

REPORT_FOLDER = "reports"
os.makedirs(REPORT_FOLDER, exist_ok=True)

def read_file(path):
    if not os.path.exists(path):
        return ""
    try:
        return open(path, "r", encoding="utf-8", errors="ignore").read()
    except Exception as e:
        return "# read error: " + str(e)

def file_status(path):
    if not os.path.exists(path):
        return "missing"
    size = os.path.getsize(path)
    return str(size) + " bytes"

def local_suggestions():
    out = []
    out.append("Elie Self-Improvement Suggestions")
    out.append("=" * 40)
    out.append("Mode: local safe review")
    out.append("")
    for f in WATCH_FILES:
        text = read_file(f)
        out.append("File: " + f + " | " + file_status(f))
        if not text:
            out.append("- Suggestion: create or restore this file if required.")
        elif "try:" not in text and f.endswith(".py"):
            out.append("- Suggestion: add safer error handling.")
        elif "checkpoint" not in text.lower() and f in ["shannon_ai.py", "shannon_core.py"]:
            out.append("- Suggestion: add version/checkpoint label inside this module.")
        else:
            out.append("- Looks usable. Review manually before changing.")
        out.append("")
    return chr(10).join(out)

def run():
    result = local_suggestions()
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    path = os.path.join(REPORT_FOLDER, "self_improve_" + stamp + ".txt")
    open(path, "w", encoding="utf-8").write(result)
    print(result)
    print("")
    print("Saved:", path)

if __name__ == "__main__":
    run()

import os, json, urllib.request
from shannon_core import build_file_report
from scope_config import PROJECT_NAME, CLIENT_TYPE, ENVIRONMENT, ALLOWED_TARGETS, ALLOWED_ACTIONS, PASSWORD_LOCKED_ACTIONS

API_TIMEOUT = 30
DEFAULT_PROVIDER = "none"
DEFAULT_MODEL = "local-fallback"

def scope_text():
    out = []
    out.append("Active Elie Scope")
    out.append("-----------------")
    out.append("Project: " + PROJECT_NAME)
    out.append("Client type: " + CLIENT_TYPE)
    out.append("Environment: " + ENVIRONMENT)
    out.append("")
    out.append("Allowed targets:")
    for x in ALLOWED_TARGETS: out.append("- " + x)
    out.append("")
    out.append("Allowed actions:")
    for x in ALLOWED_ACTIONS: out.append("- " + x)
    out.append("")
    out.append("Password-locked controlled actions:")
    for x in PASSWORD_LOCKED_ACTIONS: out.append("- " + x)
    return "\n".join(out)

def local_improve(local_map):
    out = []
    out.append("Elie Shannon AI Enhancer")
    out.append("Mode: local fallback")
    out.append("=" * 32)
    out.append(local_map)
    out.append("")
    out.append("AI/API layer is prepared but not active yet.")
    return "\n".join(out)

SYSTEM_PROMPT = "You are Elie Shannon AI Enhancer for authorized defensive security review. Improve code/server/API security findings, rank risk, explain impact, and give safe fixes. Do not perform uncontrolled actions."

def call_openai_compatible(url, key, model, local_map):
    prompt = "Improve this authorized Shannon-style security review. Include prioritized findings, risk reasoning, and fixes.\\n\\n" + local_map
    data = {
        "model": model,
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": prompt}
        ],
        "temperature": 0.2,
        "max_tokens": 900
    }
    req = urllib.request.Request(
        url,
        data=json.dumps(data).encode("utf-8"),
        headers={"Authorization": "Bearer " + key, "Content-Type": "application/json", "User-Agent": "Mozilla/5.0"},
        method="POST"
    )
    with urllib.request.urlopen(req, timeout=API_TIMEOUT) as r:
        raw = r.read().decode("utf-8")
        obj = json.loads(raw)
        return obj["choices"][0]["message"]["content"]

def improve_with_api(local_map):
    provider = os.environ.get("ELIE_API_PROVIDER", DEFAULT_PROVIDER).lower().strip()
    model = os.environ.get("ELIE_API_MODEL", DEFAULT_MODEL).strip()
    if provider == "none" or not provider:
        return local_improve(local_map)
    if provider == "groq":
        key = os.environ.get("GROQ_API_KEY", "").strip()
        if not key:
            return "Groq key missing. Using local fallback.\\n\\n" + local_improve(local_map)
        if model == "local-fallback": model = "llama-3.1-8b-instant"
        try:
            return call_openai_compatible("https://api.groq.com/openai/v1/chat/completions", key, model, local_map)
        except Exception as e:
            return "Groq failed. Using local fallback. Error: " + str(e) + "\\n\\n" + local_improve(local_map)
    if provider == "openrouter":
        key = os.environ.get("OPENROUTER_API_KEY", "").strip()
        if not key:
            return "OpenRouter key missing. Using local fallback.\\n\\n" + local_improve(local_map)
        if model == "local-fallback": model = "openrouter/auto"
        try:
            return call_openai_compatible("https://openrouter.ai/api/v1/chat/completions", key, model, local_map)
        except Exception as e:
            return "OpenRouter failed. Using local fallback. Error: " + str(e) + "\\n\\n" + local_improve(local_map)
    return "Unknown API provider: " + provider + "\\n\\n" + local_improve(local_map)

def run(name):
    local_map = scope_text() + "\n\n" + build_file_report(name)
    return improve_with_api(local_map)

