def now_id():
    return datetime.now().strftime("%Y%m%d_%H%M%S")

def send_message(sender, receiver, topic, body):
    msg_id = now_id()
    path = MESSAGES / f"{msg_id}_{sender}_to_{receiver}.txt"

    content = (
        f"FROM: {sender}\n"
        f"TO: {receiver}\n"
        f"TOPIC: {topic}\n"
        f"TIME: {datetime.now().isoformat()}\n\n"
        f"{body}\n"
    )

    path.write_text(content, encoding="utf-8")
    return str(path)

def read_latest_messages(limit=5):
    files = sorted(MESSAGES.glob("*.txt"), key=lambda p: p.stat().st_mtime, reverse=True)
    output = []

    for f in files[:limit]:
        try:
            output.append(f"--- {f.name} ---\n" + f.read_text(encoding="utf-8", errors="ignore"))
        except Exception:
            pass

    return "\n\n".join(output) if output else "No bridge messages yet."

def save_decision(title, body):
    safe_title = title.replace(" ", "_").replace("\\", "_").replace("/", "_")[:40]
