BACKUPS = PROJECTS / "backups"
CURRENT = PROJECTS / "current_project.json"

for folder in [PROJECTS, PLANS, BACKUPS]:
    folder.mkdir(parents=True, exist_ok=True)

SKIP_DIRS = {
    ".git",
    "__pycache__",
    "node_modules",
    "venv",
    ".venv",
    "env",
    "dist",
    "build",
    "backups",
    "desktop_uploads",
    "desktop_voice",
}

ALLOWED_EXT = {
    ".py",
    ".md",
    ".txt",
    ".json",
    ".yaml",
    ".yml",
    ".html",
    ".css",
    ".js",
    ".ts",
    ".tsx",
    ".jsx",
}

PROTECTED_NAMES = {
    ".env",
    "groq_key.txt",
    "openrouter_key.txt",
    "sambanova_key.txt",
    "gemini_key.txt",
}

def now():
    return datetime.now().strftime("%Y%m%d_%H%M%S")

def save_current_project(path):
    target = Path(path).expanduser().resolve()

    if not target.exists():
        return "Project path not found: " + str(target)

    if not target.is_dir():
        return "Project path must be a folder: " + str(target)

    data = {
        "path": str(target),
        "selected_at": datetime.now().isoformat()
    }

    CURRENT.write_text(json.dumps(data, indent=2), encoding="utf-8")

    return "Project selected:\n" + str(target)

def get_current_project():
    if not CURRENT.exists():
        return None

    try:
        data = json.loads(CURRENT.read_text(encoding="utf-8"))
        path = Path(data["path"]).resolve()
        if path.exists() and path.is_dir():
            return path
    except Exception:
        return None

    return None

def project_status():
    project = get_current_project()

    if not project:
        return "No project selected. Use: /project select path"

    latest_plan = latest_plan_file()

    out = "Current Ray project:\n" + str(project)

    if latest_plan:
        out += "\n\nLatest plan:\n" + str(latest_plan)
    else:
        out += "\n\nNo plan yet."

    return out

def is_skipped(path):
    parts = {p.lower() for p in path.parts}
    return any(skip.lower() in parts for skip in SKIP_DIRS)

def is_protected(path):
    name = path.name.lower()

    if name in PROTECTED_NAMES:
        return True

    if "vault" in [p.lower() for p in path.parts]:
        return True

    return False

def collect_project_files(project):
    files = []

    for f in project.rglob("*"):
        if not f.is_file():
            continue

        if is_skipped(f):
            continue

        if is_protected(f):
            continue

        if f.suffix.lower() not in ALLOWED_EXT:
            continue

        try:
            size = f.stat().st_size
        except Exception:
            size = 0

        if size > 300000:
            continue

        rel = str(f.relative_to(project)).replace("\\", "/")
        files.append((rel, size, f))

    return files

def project_snapshot(project, preview_limit=25):
    files = collect_project_files(project)

    file_list = "\n".join([f"- {rel} ({size} bytes)" for rel, size, _ in files[:300]])

    previews = []
    for rel, size, f in files[:preview_limit]:
        try:
            text = f.read_text(encoding="utf-8", errors="ignore")[:1400]
            previews.append(f"FILE: {rel}\n{text}")
        except Exception:
            pass

    return {
        "file_count": len(files),
        "file_list": file_list,
        "previews": "\n\n---\n\n".join(previews)
    }

def create_project_backup(project):
    out = BACKUPS / f"project_backup_{project.name}_{now()}.zip"

    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
        for f in project.rglob("*"):
            if not f.is_file():
                continue

            if is_skipped(f):
                continue

            if is_protected(f):
                continue

            rel = str(f.relative_to(project)).replace("\\", "/")
            z.write(f, rel)

