PROTECTED_PARTS = [
    "vault",
    "ops/backups",
    "__pycache__",
]

ALLOWED_EXT = [
    ".py",
    ".md",
    ".txt",
    ".json",
]

def now():
    return datetime.now().strftime("%Y%m%d_%H%M%S")

def rel(path):
    return str(path.relative_to(ROOT)).replace("\\", "/")

def is_protected(path):
    r = rel(path).lower()
    for part in PROTECTED_PARTS:
        if part in r:
            return True
    return False

def backup_project():
    out = BACKUPS / f"ray_backup_{now()}.zip"

    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
        for p in ROOT.rglob("*"):
            if not p.is_file():
                continue

            r = rel(p)

            if "ray/ops/backups/" in r:
                continue
            if "__pycache__" in r:
                continue
            if "ray/vault/" in r:
                continue

            z.write(p, r)

    return out

